<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { useSessionStore } from '../stores/session'
import { configured, demoMode, requireBackend } from '../lib/supabase'
import { listGames, listOptions } from '../lib/api'
import type { Game, Option } from '../lib/models'
interface Report { id:string; reporter_id:string; reported_id:string; category:string; description:string; status:string; created_at:string }
const session=useSessionStore(), allowed=computed(()=>Boolean(session.user && session.admin))
const reports=ref<Report[]>([]),games=ref<Game[]>([]),options=ref<Option[]>([]),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const gameId=ref(''),kind=ref('rank'),code=ref(''),label=ref(''),reason=ref(''),reportId=ref(''),subjectId=ref(''),action=ref('hide_profile')
async function load(){if(!allowed.value||(!configured && !demoMode))return;loading.value=true;error.value='';try{const [result,g]=await Promise.all([requireBackend().from('reports').select('id,reporter_id,reported_id,category,description,status,created_at').order('created_at',{ascending:false}).limit(100),listGames()]);if(result.error)throw result.error;reports.value=(result.data||[]) as Report[];games.value=g}catch{error.value='Data moderasi tidak dapat dimuat. Periksa izin admin dan koneksi.'}finally{loading.value=false}}
onMounted(load)
async function loadOptions(){options.value=[];if(!gameId.value)return;try{options.value=await listOptions(gameId.value)}catch{error.value='Opsi katalog tidak dapat dimuat.'}}
async function moderate(){if(!allowed.value||!subjectId.value||reason.value.trim().length<10)return;if(!confirm('Terapkan tindakan moderasi ini? Alasan akan dicatat dalam audit.'))return;busy.value=true;error.value='';notice.value='';try{const {error:failure}=await requireBackend().rpc('apply_moderation_action',{p_subject:subjectId.value,p_report:reportId.value||null,p_action:action.value,p_reason:reason.value.trim()});if(failure)throw failure;notice.value='Tindakan moderasi tercatat.';reason.value='';await load()}catch{error.value='Tindakan ditolak. Periksa izin dan status laporan.'}finally{busy.value=false}}
async function addOption(){if(!allowed.value||!gameId.value||!code.value.trim()||!label.value.trim())return;busy.value=true;error.value='';notice.value='';try{const {error:failure}=await requireBackend().rpc('add_catalog_option',{p_game:gameId.value,p_kind:kind.value,p_code:code.value.trim(),p_label:label.value.trim()});if(failure)throw failure;notice.value='Opsi katalog ditambahkan.';code.value='';label.value='';await loadOptions()}catch{error.value='Opsi gagal disimpan. RPC katalog admin belum tersedia atau aturan katalog menolak isian.'}finally{busy.value=false}}
function selectReport(r:Report){reportId.value=r.id;subjectId.value=r.reported_id}
</script>
<template><main class="admin"><nav class="crumb"><RouterLink to="/">Mabar Finder</RouterLink> › Admin Panel</nav><header class="admin-head"><div><span class="eyebrow">ADMIN PANEL</span><h1>Dashboard Statistik &amp; Moderasi</h1><p>Moderasi laporan dan kelola opsi katalog. Semua tindakan diperiksa di server.</p></div><span class="shield">⬡</span></header><p v-if="!configured && !demoMode" role="alert" class="error">Layanan belum dikonfigurasi.</p><p v-else-if="session.loading" role="status">Memeriksa akses…</p><p v-else-if="!session.user">Silakan <RouterLink to="/login">masuk</RouterLink>.</p><p v-else-if="!allowed" role="alert" class="error">Akses ditolak. Halaman ini hanya untuk admin.</p><template v-else><p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="notice" role="status" class="success">{{ notice }}</p><button class="secondary" :disabled="loading" @click="load">Muat ulang</button><p v-if="loading" role="status">Memuat laporan…</p><section class="panel"><div class="panel-heading"><span class="section-icon">⚑</span><div><span class="eyebrow">KEAMANAN KOMUNITAS</span><h2>Pusat Laporan &amp; Moderasi</h2></div><span class="count">{{ reports.length }} laporan</span></div><p v-if="!loading&&!reports.length">Belum ada laporan yang dapat dilihat.</p><div class="report-list"><article v-for="r in reports" :key="r.id"><strong>{{ r.category }} · {{ r.status }}</strong><small>{{ new Date(r.created_at).toLocaleString('id-ID') }}</small><p>{{ r.description }}</p><button class="secondary" @click="selectReport(r)">Tindak laporan</button></article></div><form @submit.prevent="moderate"><h3>Tindakan moderasi</h3><label>ID laporan (opsional)<input v-model="reportId" type="text" placeholder="Pilih laporan di atas"></label><label>ID pengguna sasaran<input v-model="subjectId" required placeholder="Pilih laporan di atas"></label><label>Tindakan<select v-model="action"><option value="hide_profile">Sembunyikan profil</option><option value="suspend_user">Suspend pengguna</option><option v-if="!demoMode" value="restrict_account">Batasi akun</option><option v-if="!demoMode" value="restore_profile">Pulihkan profil</option><option v-if="!demoMode" value="restore_account">Pulihkan akun</option></select></label><label>Alasan audit<textarea v-model="reason" minlength="10" maxlength="1000" rows="3" required></textarea></label><p>Proses server harus mencatat audit, memberi tahu pengguna, dan menyediakan jalur banding.</p><button :disabled="busy||reason.trim().length<10">Terapkan tindakan</button></form></section><section class="panel"><h2>Katalog game</h2><label>Game<select v-model="gameId" @change="loadOptions"><option value="">Pilih game</option><option v-for="g in games" :key="g.id" :value="g.id">{{ g.name }}</option></select></label><ul><li v-for="o in options" :key="o.id">{{ o.kind }} · {{ o.label }} ({{ o.code }})</li></ul><form v-if="gameId" @submit.prevent="addOption"><h3>Tambah opsi</h3><label>Jenis<select v-model="kind"><option v-for="k in ['rank','role','mode','region','server','map','hero','agent','perspective','team_size']" :key="k" :value="k">{{ k }}</option></select></label><label>Kode<input v-model="code" required maxlength="60" pattern="[a-z0-9_-]+" title="Huruf kecil, angka, garis bawah atau tanda hubung"></label><label>Label<input v-model="label" required maxlength="100"></label><button :disabled="busy">Tambah opsi</button></form><p>Opsi lama dipertahankan sebagai referensi historis; perubahan season memerlukan alur tersendiri.</p></section></template></main></template>
<style scoped>
.admin{max-width:1280px}.crumb{color:#a0a0b2;font-size:.85rem;margin-bottom:2rem}.crumb a{color:#a0a0b2}.admin-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #343442;padding-bottom:1.5rem}.admin-head h1{font:800 clamp(1.8rem,4vw,2.5rem) "Plus Jakarta Sans",sans-serif;margin:.5rem 0}.eyebrow{color:#c8ff4d;font-weight:800;font-size:.7rem;letter-spacing:.16em}.shield{width:64px;height:64px;display:grid;place-items:center;background:#303823;color:#c8ff4d;border-radius:18px;font-size:2rem}.admin .panel{border-radius:20px;padding:2rem}.panel-heading{display:flex;align-items:center;gap:1rem;margin-bottom:1.5rem}.panel-heading h2{margin:.3rem 0;font:700 1.35rem "Plus Jakarta Sans",sans-serif}.section-icon{width:48px;height:48px;display:grid;place-items:center;background:#323d27;border-radius:12px;color:#c8ff4d}.count{margin-left:auto;background:#34343d;border-radius:50px;padding:.4rem .8rem;font-size:.8rem}.admin .report-list article{background:#272736;border-color:#434353;border-radius:14px;padding:1.5rem}.admin .report-list article strong{color:#c8ff4d}.admin form{border-top:1px solid #434353;padding-top:1.5rem}.admin input,.admin select,.admin textarea{border-radius:10px;background:#272736}
.admin{max-width:1100px;margin:auto;padding:2rem 1.25rem 5rem;color:#f5f3ee}.panel{background:#1e1e29;border:1px solid #3b3b49;border-radius:18px;padding:1.5rem;margin:1.5rem 0}.report-list{display:grid;gap:.75rem}.report-list article{border:1px solid #444453;border-radius:10px;padding:1rem;overflow-wrap:anywhere}.report-list small{display:block;color:#aaa}.report-list p{white-space:pre-wrap}form{max-width:650px;display:grid;gap:.8rem;margin:2rem 0}label{display:grid;gap:.4rem}input,select,textarea{background:#14141c;border:1px solid #575766;border-radius:8px;padding:.75rem;color:#f5f3ee;font:inherit;max-width:100%;box-sizing:border-box}button{background:#c8ff4d;color:#14141c;border:0;border-radius:8px;padding:.7rem 1rem;font-weight:700;cursor:pointer}.secondary{background:#30303f;color:#f5f3ee}button:disabled{opacity:.5}p{color:#b9b9c7}.error{color:#ffb4ab}.success,a{color:#c8ff4d}:focus-visible{outline:3px solid #8b7cff;outline-offset:2px}</style>
